{"file_path": "C:\Users\UserX\.zcode\workspace\default\du\dates-hist.ps1", "content": "param([Parameter(Mandatory=$true)][string]$Root)
$ErrorActionPreference='SilentlyContinue'
$groups = @{}
Get-ChildItem -LiteralPath $Root -Recurse -File -Force | ForEach-Object {
  $m = $_.LastWriteTime.ToString('yyyy-MM')
  $g = $groups[$m]
  if ($null -eq $g) { $g = [pscustomobject]@{MB=0.0;N=0}; $groups[$m] = $g }
  $g.MB += $_.Length/1MB
  $g.N++
}
$groups.GetEnumerator() | Sort-Object Name | ForEach-Object { '{0}  {1,10:N0} MB  {2,8} files' -f $_.Key, $_.Value.MB, $_.Value.N }
exit 0
"}

